<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Topup; use App\Models\Transaction; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class TopupController extends Controller{ public function index(Request $request){$q=Topup::with('user')->latest(); if($request->filled('status'))$q->where('status',$request->status); $topups=$q->paginate(10)->withQueryString(); return view('admin.topups.index',compact('topups'));} public function approve(Topup $topup){if($topup->status!=='pending')return back()->with('error','Top up sudah diproses.');DB::transaction(function()use($topup){$wallet=$topup->user->wallet()->lockForUpdate()->firstOrCreate(['user_id'=>$topup->user_id],['balance'=>0]);$wallet->balance+=$topup->amount;$wallet->save();$topup->update(['status'=>'success']);Transaction::create(['user_id'=>$topup->user_id,'type'=>'topup','amount'=>$topup->amount,'status'=>'success','description'=>'Top up approved by admin','reference_no'=>$topup->reference_no]);}); return back()->with('success','Top up berhasil di-approve.');} public function reject(Topup $topup){if($topup->status!=='pending')return back()->with('error','Top up sudah diproses.');$topup->update(['status'=>'failed']); return back()->with('success','Top up ditolak.');}}
